'use strict';
(()=>{
 const G=JustinGame,P=G.Progression,game=window.justinClicker,$=id=>document.getElementById(id);
 const icon=name=>'<img class="ui-icon" src="assets/icons/'+name+'.svg" alt="">';
 $('settings-open').innerHTML=icon('settings');$('settings-open').setAttribute('aria-label','Settings');$('settings-open').title='Settings';
 const soundSettings=document.createElement('fieldset');soundSettings.innerHTML='<legend>Click sound</legend>';for(const label of document.querySelectorAll('.click-sound-controls label'))soundSettings.append(label);$('settings').append(soundSettings);$('change-dance').innerHTML=icon('bolt')+' Shuffle dance';for(const [id,name]of [['backdrops-open','palette'],['yeet-face','bolt']]){const img=document.createElement('img');img.className='ui-icon';img.src='assets/icons/'+name+'.svg';img.alt='';$(id).prepend(img)}
 $('leaderboard-open').innerHTML=icon('cup')+'<span>Ranks</span>';
 document.querySelector('header>span').textContent='JUSTIN CLICKER';
 document.querySelector('.shop-title h2').textContent='THE JUSTIN ECONOMY';
 document.querySelector('.shop-title>span').textContent='Justin shop';
 $('faces-tab').textContent='Justins';$('business-tab').textContent='Upgrades';const tabs=$('faces-tab').parentElement;tabs.prepend($('business-tab'));
 const dock=document.createElement('nav');dock.className='reward-dock';dock.setAttribute('aria-label','Rewards');
 dock.innerHTML='<button id="daily-open">'+icon('gift')+'<span>Daily gift</span><i id="gift-dot" hidden></i></button><button id="collection-open">'+icon('book')+'<span>Collection <small id="collection-count"></small></span></button><button id="tasks-open">'+icon('bolt')+'<span>Challenges</span><i id="task-dot" hidden></i></button>';
 document.querySelector('.game-score').before(dock);const backdropButton=$('backdrops-open');backdropButton.classList.add('backdrop-feature');backdropButton.innerHTML=icon('palette')+'<span><b>Backdrops</b><small>Change your background</small></span><span class="backdrop-samples" aria-hidden="true"><img src="assets/backdrops/bg-6143-thumb.jpg" alt=""><img src="assets/backdrops/bg-6157-thumb.jpg" alt=""><img src="assets/backdrops/bg-6146-thumb.jpg" alt=""></span>';dock.append(backdropButton);
 const eventBar=document.createElement('section');eventBar.className='event-strip';eventBar.setAttribute('aria-label','Community events');eventBar.innerHTML='<div><b>COMMUNITY CLICKS</b><span id="community-total">Connecting…</span></div><progress id="community-meter" max="10000" value="0"></progress><div><button id="community-open">'+icon('cup')+' Community</button><span id="invasion-clock"></span></div>';
 document.querySelector('.game-tools').after(eventBar);
 const dialog=document.createElement('dialog');dialog.id='rewards-dialog';dialog.className='online-dialog rewards-dialog';dialog.innerHTML='<div class="online-dialog-head"><h2 id="rewards-title"></h2><button id="rewards-close" aria-label="Close rewards">'+icon('close')+'</button></div><div id="rewards-content"></div><p id="reward-message" role="status" aria-live="polite"></p>';document.body.append(dialog);
 $('rewards-close').onclick=()=>dialog.close();
 let view='',signature='',lastReward=game.snapshot().lastReward?.id,community={total:0,epoch:1},offset=0,loadingCommunity=false,guestNote=false;
 const number=n=>Math.floor(n||0).toLocaleString(),clock=ms=>{const sec=Math.max(0,Math.ceil(ms/1000));return Math.floor(sec/3600)?Math.floor(sec/3600)+'h '+Math.floor(sec/60)%60+'m':Math.floor(sec/60)+'m '+sec%60+'s'};
 const now=()=>Date.now()+offset;
 function open(next){view=next;signature='';$('reward-message').textContent='';dialog.showModal();update()}
 $('daily-open').onclick=()=>open('daily');$('collection-open').onclick=()=>open('book');$('tasks-open').onclick=()=>open('tasks');$('community-open').onclick=()=>open('community');
 function action(kind,data){$('reward-message').textContent=game.ranked()?'Checking your reward…':'';game.featureAction(kind,data);signature='';update()}
 function button(text,fn,disabled=false){const b=document.createElement('button');b.type='button';b.textContent=text;b.disabled=disabled;b.onclick=fn;return b}
 function node(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
 function portrait(id,locked=false){const image=document.createElement('img');image.className='book-portrait'+(locked?' undiscovered':'');image.alt='';image.dataset.portrait=id;image.src='assets/friend.png';return image}
 function portraits(){for(const img of dialog.querySelectorAll('[data-portrait]')){const skin=G.skins.find(s=>s.id===img.dataset.portrait),url=window.JustinSprites?.url(skin);if(url&&img.src!==url)img.src=url}}
 function daily(s,root){const p=P.prepare(s,now()),claimed=p.giftDay>=P.day(now());root.append(node('p',claimed?'Delivery received. Next one in '+clock(P.nextDay(now())-now()):'One delivery each day. Pick a box.','reward-subtitle'));
  const boxes=node('div',null,'gift-boxes');for(let i=0;i<3;i++){const b=button('',()=>action('daily-gift'),claimed||game.ranked()&&!window.justinOnline.connected());b.innerHTML=icon('gift')+'<span>'+(claimed?'Opened':'BOX '+(i+1))+'</span>';b.setAttribute('aria-label','Open daily gift box '+(i+1));boxes.append(b)}root.append(boxes);
  if(claimed&&s.lastGift){const reveal=node('div',null,'reward-reveal');if(s.lastGift.skin)reveal.append(portrait(s.lastGift.skin));else reveal.innerHTML=icon('coin');reveal.append(node('b',s.lastGift.skin?s.lastGift.label:'+'+number(s.lastGift.amount)+' points'));root.append(reveal)}
  const track=node('div',null,'delivery-track');for(let i=1;i<=5;i++)track.append(node('span',i<=p.weekDays.length?'✓':String(i),i<=p.weekDays.length?'done':''));root.append(track,node('p',Math.min(5,p.weekDays.length)+'/5 deliveries this week · bonus on the fifth. Missed days don’t erase progress.','reward-subtitle'));
  const details=node('details');details.innerHTML='<summary>What’s inside?</summary><p>Every box: guaranteed points. All three boxes have the same odds.</p><p>Platinum 20% · Diamond 8% · Rainbow 2% · Gold 10% · points 60%. Justins add click power. Duplicates give extra points.</p><p>Guaranteed by lifetime gift 7 / 30 / 90 respectively. No streak needed. Daily reset: midnight Singapore time.</p>';root.append(details,node('small','Lifetime deliveries: '+p.gifts));
 }
 function book(s,root){root.append(node('p',s.owned.length+' / '+G.skins.length+' found','reward-subtitle'));const milestones=node('div',null,'book-milestones');for(const count of [5,10,15,20])milestones.append(button(s.progress.book.includes(count)?count+' ✓':count+' finds → gift',()=>action('book-reward',{count}),s.owned.length<count||s.progress.book.includes(count)));root.append(milestones);
  const grid=node('div',null,'collection-grid'),priority=['normal','chair','stairs','purple','platinum','diamond','rainbow'];for(const skin of [...G.skins].sort((a,b)=>(priority.includes(a.id)?priority.indexOf(a.id):99)-(priority.includes(b.id)?priority.indexOf(b.id):99))){const owned=s.owned.includes(skin.id),card=node('article',null,'collection-card '+(owned?'found':'locked'));card.dataset.rarity=skin.rarity||'common';card.append(portrait(skin.id,!owned),node('b',skin.name),node('small',(skin.power?'+'+skin.power+' / click · ':'')+(skin.rarity|| (skin.luckyOnly?'rare':'original'))));card.append(node('p',owned?'Collected':skin.tag));if(owned)card.append(button(s.equipped===skin.id?'Wearing':'Wear',()=>action('equip',{id:skin.id}),s.equipped===skin.id));else if(skin.cost!==null)card.append(node('small',number(skin.cost)+' points · shop'));grid.append(card)}root.append(grid);
 }
 function tasks(s,root){root.append(node('p','New challenges in '+clock(P.nextDay(now())-now()),'reward-subtitle'));const p=P.prepare(s,now());for(const t of P.tasksAt(now())){const count=Math.min(t.goal,Math.max(0,t.value(s,p))),card=node('article',null,'task-card');card.innerHTML=icon(t.id==='crit'?'bolt':t.id==='buy'?'coin':'check');const info=node('div');info.append(node('b',t.name),node('small',p.tasks.includes(t.id)?'Completed today':count+' / '+t.goal));const meter=document.createElement('progress');meter.max=t.goal;meter.value=p.tasks.includes(t.id)?t.goal:count;info.append(meter,node('small','+'+number(P.scaled(s,t.base))+' points'));card.append(info,button(p.tasks.includes(t.id)?'Claimed':'Claim',()=>action('challenge',{id:t.id}),count<t.goal||p.tasks.includes(t.id)));root.append(card)}}
 function communityView(s,root){root.append(node('p',game.ranked()?'Every full-value ranked click contributes.':'Community rewards need an account. Guest rewards stay on this device.','reward-subtitle'));for(const goal of [10000,50000,200000,1000000]){const card=node('article',null,'task-card');card.innerHTML=icon('cup');card.append(node('b',number(goal)+' clicks'+(goal===50000?' · Party Justin':'')),button(s.progress.community.includes(goal)?'Claimed':'Claim',()=>action('community-reward',{goal}),!game.ranked()||community.total<goal||s.clicks<1||s.progress.community.includes(goal)));root.append(card)}root.append(node('p','Justin invasion: first two minutes of every hour. Catch up to three escapees for bonus points.','reward-subtitle'))}
 function update(){if(document.hidden)return;let celebrate=false;const s=game.snapshot(),at=now(),p=P.prepare(s,at),invasion=P.invasion(at);$('gift-dot').hidden=p.giftDay>=P.day(at);$('task-dot').hidden=!P.tasksAt(at).some(t=>!p.tasks.includes(t.id)&&t.value(s,p)>=t.goal);$('collection-count').textContent=s.owned.length+'/'+G.skins.length;
  const goal=[10000,50000,200000,1000000].find(n=>community.total<n)||1000000;$('community-total').textContent=number(community.total)+' / '+number(goal);$('community-meter').max=goal;$('community-meter').value=Math.min(goal,community.total);$('invasion-clock').textContent=invasion.active?'INVASION · '+clock(invasion.ends-at):'Invasion in '+clock(invasion.next-at);
  escapes(s,invasion);
  if(s.lastReward&&s.lastReward.id!==lastReward&&s.lastReward.id!==s.lastRoll?.id){lastReward=s.lastReward.id;celebrate=true;const text=s.lastReward.label+' · +'+number(s.lastReward.amount)+' points';$('reward-message').textContent=text;toast(text);if(!$('gentle').checked){$('daily-open').animate([{transform:'rotate(-6deg) scale(.95)'},{transform:'rotate(5deg) scale(1.08)'},{transform:'none'}],{duration:400});if(!dialog.open)burst(w/2,h*.45,16)}}
  if(!dialog.open)return;const next=JSON.stringify([view,p,s.owned,s.equipped,s.clicks,s.critHits,s.purchases,community.total,view==='book'?0:Math.floor(at/1000)]);if(next!==signature){signature=next;const root=$('rewards-content');const focused=document.activeElement,focusIndex=focused&&root.contains(focused)?[...root.querySelectorAll('button')].indexOf(focused):-1;const scroll=dialog.scrollTop;root.replaceChildren();$('rewards-title').textContent={daily:'Daily gift',book:'Collection',tasks:'Daily challenges',community:'COMMUNITY CLICKS'}[view];({daily,book,tasks,community:communityView}[view])(s,root);dialog.scrollTop=scroll;if(focusIndex>=0)root.querySelectorAll('button')[focusIndex]?.focus({preventScroll:true});}portraits();if(celebrate&&!$('gentle').checked)dialog.querySelector('.reward-reveal')?.animate([{transform:'scale(.9) rotate(-2deg)',opacity:.4},{transform:'scale(1.025) rotate(1deg)',opacity:1},{transform:'none'}],{duration:450,easing:'ease-out'})
 }
 const escapeButtons=[];for(let slot=0;slot<3;slot++){const b=button('',()=>{action('catch-justin',{slot});b.hidden=true});b.className='escape-justin';b.setAttribute('aria-label','Catch escaped Justin '+(slot+1));b.innerHTML='<img src="assets/friend.png" alt="">';b.style.setProperty('--escape-left',(8+slot*34)+'%');b.style.setProperty('--escape-delay',(-slot*2)+'s');b.hidden=true;document.querySelector('.game-play').append(b);escapeButtons.push(b)}
 function escapes(s,event){for(let slot=0;slot<3;slot++)escapeButtons[slot].hidden=!event.active||dialog.open||(s.progress.encounterHour===event.hour&&s.progress.encounters.includes(slot))}
 async function loadCommunity(){if(loadingCommunity||document.hidden)return;loadingCommunity=true;try{const data=await window.justinOnline.community();community=data;offset=data.serverNow-Date.now();update()}catch{if(!guestNote){$('community-total').textContent='Community offline';guestNote=true}}finally{loadingCommunity=false}}
 setInterval(update,1000);setInterval(loadCommunity,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){loadCommunity();update()}});loadCommunity();update();
})();
